  else if(token.startsWith('"')&&stack.at(-1)?.object&&stack.at(-1).key){
   const frame=stack.at(-1),key=JSON.parse(token);if(frame.keys.has(key))fail('idp_json_invalid');frame.keys.add(key);frame.key=false;
